import {api as request,browserMode,ready} from './browser-api.js';
const $=id=>document.getElementById(id),esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));let manifest,record,dirty=false,version=0,saving=null,timer,activeFilter='all';
function message(t,error=false){$('discussionStatus').textContent=t;$('discussionStatus').classList.toggle('error',error);}
function render(){const r=manifest.review;$('reviewScope').textContent=`已对现存 ${r.currentImagesReviewed} 张图片逐图初筛，本次补入 ${r.newCurrentCandidates} 张现存候选及 ${r.newHistoricalExamples} 张历史剔除图。重点残卷用于讨论完整整页的保留口径；残损可用候选倾向保留。蓝色框均来自已有坐标，不是新增标注。`;$('discussionStats').innerHTML=`<b>${manifest.files.length}<span>张讨论图例</span></b><b>${r.newCurrentCandidates}<span>张新增现存候选</span></b>`;renderFilters();const opts=['待讨论','建议保留','建议剔除','补标后保留'];$('fragmentCards').innerHTML=manifest.files.map(f=>{const d=record.items[f.name]||{decision:'待讨论',note:''};return `<article class="fragment-card ${f.bucket}" data-name="${f.name}"><div class="fragment-title"><h2>${f.name}</h2><span class="status-tag ${f.currentStatus==='当前保留'?'keep':''}">${f.currentStatus} · ${f.group}</span></div><button class="fragment-image" data-image="${f.name}" aria-label="放大 ${f.name} 原图"><img src="${f.image}" alt="${f.name} 原图" loading="lazy"></button><div class="fragment-body"><div class="fragment-meta">${f.width} × ${f.height} 像素 · 现有 ${f.boxes} 个框</div><p class="fragment-reason"><b>${esc(f.recommendation)}：</b>${esc(f.reason)}</p><div class="decision-row"><label>讨论结论<select data-decision="${f.name}">${opts.map(o=>`<option ${d.decision===o?'selected':''}>${o}</option>`).join('')}</select></label></div><label>讨论备注<textarea data-note="${f.name}" placeholder="记录师兄的意见或保留条件">${esc(d.note)}</textarea></label></div></article>`;}).join('');toggleBoxes();filterCards();}
const filterLabels={all:'全部',priority:'重点残卷',moderate:'残损可用候选',removed:'历史已剔除',control:'保留对照'};
function renderFilters(){$('fragmentFilters').innerHTML=Object.entries(filterLabels).map(([key,label])=>`<button data-filter="${key}" aria-pressed="${key===activeFilter}">${label} <b>${key==='all'?manifest.files.length:manifest.files.filter(f=>f.bucket===key).length}</b></button>`).join('');}
function filterCards(){const q=$('fragmentSearch').value.trim();let count=0;for(const f of manifest.files){const visible=(activeFilter==='all'||f.bucket===activeFilter)&&(!q||f.name.includes(q));document.querySelector(`[data-name="${f.name}"]`).hidden=!visible;if(visible)count++;}$('visibleCount').textContent=`显示 ${count} / ${manifest.files.length} 张 · 选择筛选后可打印当前结果`;for(const b of $('fragmentFilters').querySelectorAll('button'))b.setAttribute('aria-pressed',String(b.dataset.filter===activeFilter));}
$('fragmentFilters').onclick=e=>{const b=e.target.closest('[data-filter]');if(b){activeFilter=b.dataset.filter;filterCards();}};$('fragmentSearch').oninput=filterCards;
function toggleBoxes(){const show=$('fragmentBoxes').checked;for(const f of manifest.files)document.querySelector(`[data-image="${f.name}"] img`).src=show?f.overlay:f.image;}
function changed(name,key,value){record.items[name]??={decision:'待讨论',note:''};record.items[name][key]=value;version++;dirty=true;message('待保存…');clearTimeout(timer);timer=setTimeout(save,600);}
async function save(){clearTimeout(timer);if(saving)return saving;if(!dirty)return true;saving=(async()=>{while(dirty){const v=version;try{const d=await request('/api/discussion',{revision:record.revision,items:record.items});record.revision=d.revision;if(v===version)dirty=false;}catch(e){message('未保存：'+e.message,true);return false;}}message('讨论记录已保存');return true;})().finally(()=>saving=null);return saving;}
$('fragmentCards').onchange=e=>{if(e.target.dataset.decision)changed(e.target.dataset.decision,'decision',e.target.value);};$('fragmentCards').oninput=e=>{if(e.target.dataset.note)changed(e.target.dataset.note,'note',e.target.value);};$('fragmentCards').onclick=e=>{const b=e.target.closest('[data-image]');if(!b)return;const f=manifest.files.find(f=>f.name===b.dataset.image);$('fullImage').src=$('fragmentBoxes').checked?f.overlay:f.image;$('imageTitle').textContent=f.name+' · '+f.currentStatus;$('imageDialog').showModal();};$('closeImage').onclick=()=>$('imageDialog').close();$('fragmentBoxes').onchange=toggleBoxes;$('discussionStatus').onclick=save;
$('exportDiscussion').onclick=async()=>{if(!await save())return;const data={date:new Date().toISOString(),policy:manifest.policy,files:manifest.files.map(f=>({...f,...record.items[f.name]}))};const blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json;charset=utf-8'}),u=URL.createObjectURL(blob),a=document.createElement('a');a.href=u;a.download='Silk_残卷讨论记录.json';a.click();setTimeout(()=>URL.revokeObjectURL(u),30000);};$('printReport').onclick=async()=>{if(await save())window.print();};window.onbeforeunload=e=>{if(dirty||saving){e.preventDefault();e.returnValue='';}};
document.querySelector('header a').onclick=async e=>{e.preventDefault();if(await save())location.assign('./');};
try{await ready();if(browserMode)document.querySelector('.discussion-toolbar span').textContent='意见仅存当前浏览器，请导出讨论记录交回；不会修改在线原图。';[manifest,record]=await Promise.all([request('/data/fragments.json'),request('/api/discussion')]);render();message('讨论记录已加载');}catch(e){message(e.message,true);}
